<script lang="ts">
 import {enter, workspaceMotion} from "./motion";
 import {onMount} from 'svelte';import SampleCapacity from './SampleCapacity.svelte';import SamplePlanning from './SamplePlanning.svelte';import SamplePiece from './SamplePiece.svelte';import SampleReports from './SampleReports.svelte';import {api,uploadTo} from './api';import type {Row} from './types';
 let {companies,company,orders=[]}:{companies:Row[];company:string;orders:Row[]}=$props();
 let view=$state('requests'),revision=$state(0),fileIndent=$state('');
 let data:any=$state(null),detail:any=$state(null),form:any=$state(null),busy=$state(false),error=$state(''),notice=$state(''),review=$state(''),search=$state(''),category=$state('Buyer email'),stockForm:any=$state(null),option:any=$state(null),production:any=$state(null),printMode=$state('indent'),printPiece=$state(0);
 const fields=[['development_id','Approved EST / style master','style'],['booking_reference','Booking reference (if available)'],['brand','Brand'],['request_date','Request date','date'],['buyer_requested_date','Buyer requested date','date'],['buyer_required_date','Buyer required date','date'],['plan_date','Plan date','date'],['email_date','Buyer email date','date'],['email_subject','Buyer email subject'],['sample_type','Sample type','option'],['est','EST number (numbers only)'],['buyer_style','Buyer style number'],['buyer_spec','Buyer specification number'],['product','Product','option'],['description','Description'],['fit','Block / fit','option'],['factory','Sample production factory','option'],['season','Season','option'],['year','Season year'],['order_id','Linked production PO (optional)','order'],['buyer_po','Buyer PO reference (if available)'],['pattern_status','Pattern type / effort','option'],['material_id','Required ETF / ESF','material'],['fabric_choice','Fabric choice','choice'],['length_metres','Fabric required (metres)'],['alternate_material_id','Alternate ETF / ESF (if required)','material'],['alternate_reference','Alternate reference'],['fabric_in_date','Fabric-in date','date'],['fabric_expected_date','Fabric expected date','date'],['trims_expected_date','Trims expected date','date'],['copy_sample_id','Copy from indent number'],['copy_purpose','Sample to copy — purpose','purpose'],['cad_reference','CAD reference'],['spec_reference','Specification reference'],['spec_date','Specification date','date'],['spec_signed','Specification signed by'],['remake_indent_id','Remake of indent number'],['special_remarks','Special remarks'],['finishing_remarks','Finishing remarks'],['embroidery','Embroidery'],['washing','Washing']];
 const productionFields=[['pattern_by','Pattern by'],['cut_by','Cut by'],['sample_maker','Sample maker'],['pattern_plan_date','Pattern ready — plan','date'],['allocation_plan_date','Cutting allocation — plan','date'],['sewing_plan_date','Sewing handover — plan','date'],['fabric_update_date','Fabric ready date','date'],['trims_update_date','Trims ready date','date'],['style_update_date','Style ready date','date'],['readiness_note','Readiness remarks'],['handover_dc','Handover DC'],['enclosures','Enclosures: cut pattern / counter sample / audit sheet']];
 const bomFields=[['component','Component'],['reference','Article / reference'],['quantity','Quantity'],['unit','Unit'],['colour','Colour'],['size','Size'],['ticket','Thread ticket'],['thread_position','Top / bobbin'],['shade','Shade number'],['placement','Placement'],['remarks','Remarks']];
 const groups=['Pocketing','Fusing','Sewing trims','Labels','Finishing','Value additions'];
 const label=(key:string)=>fields.find(f=>f[0]===key)?.[1]||productionFields.find(f=>f[0]===key)?.[1]||key.replaceAll('_',' ');
 const material=(id:any)=>data?.materials.find((m:any)=>String(m.id)===String(id))?.code||id;
 let records=$derived((data?.records||[]).filter((r:any)=>(!company||String(r.company_id)===company)&&(!search||JSON.stringify(r).toLowerCase().includes(search.toLowerCase()))));
 let printPieces=$derived(detail?.pieces.filter((p:any)=>!printPiece||p.id===printPiece)||[]);
 let layoutPages=$derived.by(()=>{const list=[{group:'Fabric',component:'Primary fabric',reference:material(detail?.record.profile.material_id)},...(detail?.record.bom||[])];const pages=[];for(let i=0;i<Math.max(1,list.length);i+=6)pages.push(list.slice(i,i+6));return pages});
 async function load(){data=await api('/sample-requests');revision++}
 async function refreshDetail(){detail=await api('/sample-requests/'+detail.record.id);await load()}
 async function run(work:()=>Promise<void>){if(busy)return;busy=true;error='';notice='';try{await work()}catch(e){error=(e as Error).message}finally{busy=false}}
 onMount(()=>{run(load)});
 function fresh(){if(!company&&companies.length>1){error='Select a workspace company before creating a request.';return}form={company_id:Number(company||companies[0]?.id),buyer_id:'',profile:Object.fromEntries(fields.map(f=>[f[0],f[2]==='date'&&f[0]==='request_date'?new Date().toLocaleDateString('en-CA'):''])),variants:[{size:'',colour:'',quantity:1}],bom:[]}}
 async function open(id:number){await run(async()=>{detail=await api('/sample-requests/'+id);review='';fileIndent='';production=null;form=null;category=data.can_audit?'Audit sheet':!data.can_edit&&data.can_pattern?'CAD':'Buyer email'})}
 function copyRequest(){const source=structuredClone($state.snapshot(detail.record));form={company_id:source.company_id,buyer_id:source.buyer_id,profile:{...source.profile,copy_sample_id:String(detail.pieces[0]?.id||''),remake_indent_id:''},variants:source.variants,bom:source.bom};detail=null}
 function edit(){form=structuredClone($state.snapshot(detail.record));detail=null}
 async function save(action:string){await run(async()=>{const result=await api('/sample-requests'+(form.id?'/'+form.id:''),{company_id:Number(form.company_id),buyer_id:Number(form.buyer_id),profile:form.profile,variants:form.variants,bom:form.bom,version:form.version,action});form=null;await load();detail=await api('/sample-requests/'+result.id);notice=action==='submit'?'Sent to MD. Sampling receives it after approval.':'Draft saved. Add attachments before submitting.'})}
 async function decide(action:string){await run(async()=>{await api('/sample-requests/'+detail.record.id,{version:detail.record.version,action,note:review});detail=await api('/sample-requests/'+detail.record.id);await load()})}
 async function pieceAction(piece:any,action:string,result=''){await run(async()=>{await api('/sample-indents/'+piece.id,{version:piece.version,action,result,note:review,production:production?.values});detail=await api('/sample-requests/'+detail.record.id);production=null;await load()})}
 function opts(kind:string,cid:any){return [...new Set([...(data?.defaults[kind]||[]),...(data?.options||[]).filter((o:any)=>o.kind===kind&&o.company_id===Number(cid)).map((o:any)=>o.label)])] as string[]}
 async function addOption(){await run(async()=>{await api('/sample-options',{...option,company_id:Number(form.company_id)});await load();form.profile[option.kind]=option.label;option=null})}
 async function upload(event:Event){const input=event.target as HTMLInputElement;const files=Array.from(input.files||[]);await run(async()=>{for(const file of files)await uploadTo('/sample-requests/'+detail.record.id+'/files?category='+encodeURIComponent(category)+(fileIndent?'&indent_id='+fileIndent:''),file);detail=await api('/sample-requests/'+detail.record.id)});input.value=''}
 async function stockSave(){await run(async()=>{await api('/sample-stock',stockForm);stockForm=null;await load();if(detail)detail=await api('/sample-requests/'+detail.record.id);notice='Stock movement recorded.'})}
 function print(kind:string,id=0){printMode=kind;printPiece=id;setTimeout(()=>window.print(),50)}
</script>
<section class="samples" use:workspaceMotion={view}>
 <header><div><p class="eyebrow">BUYER REQUEST → MD → SAMPLING → AUDIT → HANDOVER</p><h2>Sample indents</h2><p>One indent per garment. Numbers are assigned after MD approval.</p></div><div class="actions"><button class="button secondary" disabled={busy} onclick={()=>run(load)}>Refresh</button>{#if data?.can_edit}<button class="button primary" disabled={busy} onclick={fresh}>New sample request</button>{/if}{#if data?.can_stock}<button class="button secondary" onclick={()=>stockForm={company_id:Number(company||companies[0]?.id),material_id:'',metres:'',reference:''}}>Receive sample fabric</button>{/if}</div></header>
 {#if error}<div class="form-error" role="alert">{error}</div>{/if}{#if notice}<p role="status">{notice}</p>{/if}
 <nav class="sample-tabs" aria-label="Sampling views">{#each [['requests','Requests & approval'],['plan','Plan & freeze'],['live','Live progress'],['capacity','Capacity'],['master','Master register'],['sop','How to work']] as [key,title]}<button class="button" aria-current={view===key?'page':undefined} class:primary={view===key} class:secondary={view!==key} onclick={()=>view=key}>{title}</button>{/each}</nav>
 {#if view==='sop'}<section class="sop"><h3>Sampling SOP</h3><ol><li><strong>Merchant:</strong> enter buyer, style, fabric, specification, required date, sizes and pieces. Save a draft to attach the buyer email and supporting files; submit to MD.</li><li><strong>MD:</strong> review the request. Approving generates one continuous indent number per garment, including identical size and colour pieces.</li><li><strong>Sampling coordinator:</strong> first ask Super Admin to set Capacity (tailors × pieces per day, Sunday off and holidays). In Plan &amp; freeze, select garments, set priority, preview dates and freeze. Maintain the master register and update live progress daily. Record expected and ready dates for fabric, trims and style, then plan pattern, cutting, tailor allocation, sewing, finishing, audit and handover.</li><li><strong>CAD / Sampling:</strong> complete patterns. Accept the file or record missing items. Cutting requires a clear file and recorded fabric, trims and style readiness. Allocate a sample tailor before starting sewing.</li><li><strong>Sampling:</strong> record sewing and finishing progress separately, then send to QA.</li><li><strong>QA:</strong> compare the required specification against the actual garment. Record actual/alternate fabric, trims and style, submission attempt and remarks. Approve, send for rework or reject. Rework returns through sewing, finishing and a new audit; earlier signed reports stay available.</li><li><strong>Sampling / Merchant:</strong> record the DC and handover to merchant or showroom. Enter customer and sender addresses and AWB / delivery reference when completing final handover. Print the dispatch label.</li><li><strong>Traceability:</strong> each garment keeps its indent, plan, audit reports, linked private files and action history. Live planning excludes completed and rejected garments; the master retains them.</li></ol></section>{:else if view==='capacity'}<SampleCapacity {company} onupdated={()=>revision++}/>{:else if ['live','master','plan'].includes(view)}<SamplePlanning {company} {view} {revision} canPlan={data?.can_produce} onopen={open}/>{:else}
 <label class="search">Search request, style or buyer<input bind:value={search} placeholder="Search sample requests"/></label>
 <div class="table-scroll"><table><thead><tr><th>Request</th><th>Buyer / style</th><th>Plan date</th><th>Status</th><th>Pieces</th><th></th></tr></thead><tbody>{#each records as r}<tr><td>SR-{r.id}</td><td>{r.buyer}<small>{r.profile.buyer_style} · EST {r.profile.est}</small></td><td>{r.profile.plan_date||'—'}</td><td><strong>{r.status}</strong></td><td>{r.pieces||'Pending approval'}</td><td><button class="text-button" disabled={busy} onclick={()=>open(r.id)}>Open</button></td></tr>{:else}<tr><td colspan="6">No sample requests in your current access.</td></tr>{/each}</tbody></table></div>
 {#if data?.stock.length}<details><summary>Sample fabric balances</summary><div class="table-scroll"><table><thead><tr><th>Fabric</th><th>Metres remaining</th></tr></thead><tbody>{#each data.stock.filter((s:any)=>!company||String(s.company_id)===company) as s}<tr><td>{s.code}</td><td>{s.metres}</td></tr>{/each}</tbody></table></div></details>{/if}
{/if}
</section>
{#if form}
 <div class="sample-overlay"><div role="dialog" aria-modal="true" aria-label="Sample request" tabindex="-1" class="sample-dialog" use:enter><header><div><h2>{form.id?'Edit request SR-'+form.id:'Generate sample indent'}</h2></div><button disabled={busy} class="button secondary" onclick={()=>{form=null;option=null}}>Close</button></header>
 {#if error}<div class="form-error" role="alert">{error}</div>{/if}
 <div class="form-grid"><label>Buyer<select bind:value={form.buyer_id}><option value="">Choose buyer</option>{#each data.buyers.filter((b:any)=>b.company_id===Number(form.company_id)) as b}<option value={b.id}>{b.name}</option>{/each}</select></label>
 {#each fields as [key,title,type]}<label>{title}{#if type==='option'}<div class="option-line"><select bind:value={form.profile[key]}><option value="">Select…</option>{#each opts(key,form.company_id) as o}<option>{o}</option>{/each}</select><button class="button secondary" title={'Add '+title} onclick={()=>option={kind:key,label:''}}>+</button></div>{:else if type==='style'}<select bind:value={form.profile[key]} onchange={()=>{const m=data.styles.find((m:any)=>String(m.id)===form.profile.development_id);if(m){form.profile.est=m.code.replace('EST-','');form.profile.product=m.profile.product||form.profile.product;form.profile.fit=m.profile.fit||form.profile.fit;form.profile.cad_reference=m.profile.pattern_reference||form.profile.cad_reference}}}><option value="">No linked master / legacy EST</option>{#each data.styles.filter((m:any)=>m.company_id===Number(form.company_id)&&(!m.buyer_id||m.buyer_id===Number(form.buyer_id))) as m}<option value={String(m.id)}>{m.code} · {m.profile.style_name}</option>{/each}</select>{:else if type==='choice'}<select bind:value={form.profile[key]}><option value="">Select…</option><option>Actual</option><option>Alternate</option></select>{:else if type==='order'}<select bind:value={form.profile[key]} onchange={()=>{const o=orders.find(o=>String(o.id)===form.profile.order_id);if(o){form.buyer_id=o.buyer_id;form.profile.buyer_po=o.po}}}><option value="">No production PO</option>{#each orders.filter(o=>o.company_id===Number(form.company_id)&&(!form.buyer_id||o.buyer_id===Number(form.buyer_id))) as o}<option value={String(o.id)}>{o.po}</option>{/each}</select>{:else if type==='material'}<select bind:value={form.profile[key]}><option value="">Select…</option>{#each data.materials.filter((m:any)=>m.company_id===Number(form.company_id)) as m}<option value={String(m.id)}>{m.code}</option>{/each}</select>{:else if type==='pattern'||type==='purpose'}<select bind:value={form.profile[key]}><option value="">Select…</option>{#each (type==='pattern'?['New','Modified','Existing']:['Style only','Specification only','Style and specification','Construction / make only']) as o}<option>{o}</option>{/each}</select>{:else}<input type={type==='date'?'date':'text'} bind:value={form.profile[key]} readonly={key==='request_date'||key==='est'&&!!form.profile.development_id} inputmode={key==='est'?'numeric':'text'}/>{/if}</label>{/each}
 <label class="wide">Buyer email message<textarea rows="5" bind:value={form.profile.email_message} placeholder="Paste the buyer's message. Upload supporting documents after saving."></textarea></label></div>
 {#if option}<div class="inline-editor"><label>New {label(option.kind)}<input bind:value={option.label} maxlength="100"/></label><button class="button primary" disabled={busy||!option.label.trim()} onclick={addOption}>Add option</button><button class="button secondary" onclick={()=>option=null}>Cancel</button></div>{/if}
 <h3>Sizes, colours and pieces</h3><p>Each piece receives its own number and print sheet. M × 2 + XL × 1 = 3 indents.</p>
 {#each form.variants as v,i}<div class="variant"><label>Size<input bind:value={v.size}/></label><label>Colour<input bind:value={v.colour}/></label><label>Quantity<input type="number" min="1" max="100" step="1" bind:value={v.quantity}/></label><button class="button secondary" disabled={form.variants.length===1} onclick={()=>form.variants.splice(i,1)}>Remove</button></div>{/each}<button class="button secondary" onclick={()=>form.variants.push({size:'',colour:'',quantity:1})}>Add size / colour</button>
 <h3>Sample BOM</h3>{#if !form.bom.length}<p>No components added. Click Add component to add only what you need.</p>{/if}
 {#each form.bom as b,i}<div class="bom-row"><label>Group<select bind:value={b.group}>{#each groups as g}<option>{g}</option>{/each}</select></label>{#each bomFields as [key,title]}<label>{title}<input bind:value={b[key]}/></label>{/each}<button class="text-button" onclick={()=>form.bom.splice(i,1)}>Remove component</button></div>{/each}<button class="button secondary" onclick={()=>form.bom.push({group:'Sewing trims',component:''})}>Add component</button>
 <footer><button class="button secondary" disabled={busy} onclick={()=>save('save')}>{busy?'Saving…':'Save draft'}</button><button class="button primary" disabled={busy} onclick={()=>save('submit')}>Submit to MD</button></footer></div></div>
{/if}
{#if detail}
 <div class="sample-overlay"><div role="dialog" aria-modal="true" aria-label="Sample request details" tabindex="-1" class="sample-dialog" use:enter><header><div><p class="eyebrow">REQUEST SR-{detail.record.id} · {detail.record.status}</p><h2>{detail.record.profile.buyer_style} · EST {detail.record.profile.est}</h2></div><button class="button secondary" disabled={busy} onclick={()=>{detail=null;production=null}}>Close</button></header>
 {#if error}<div class="form-error" role="alert">{error}</div>{/if}
 <div class="actions">{#if data.can_edit}<button class="button secondary" onclick={copyRequest}>Copy as new request</button>{/if}{#if ['Draft','Changes requested'].includes(detail.record.status)&&data.can_edit}<button class="button primary" onclick={edit}>Edit / submit</button>{/if}{#if detail.pieces.length}<button class="button secondary" onclick={()=>print('indent')}>Print all indents</button><button class="button secondary" onclick={()=>print('layout')}>Print swatch layout</button>{/if}</div>
 {#if detail.record.review_note}<p><strong>MD review:</strong> {detail.record.review_note}</p>{/if}
 <details open><summary>Request details</summary><div class="details-grid">{#each Object.entries(detail.record.profile) as [key,value]}{#if value}<div><strong>{label(key)}</strong><span>{key.includes('material_id')?material(value):String(value)}</span></div>{/if}{/each}</div></details>
 <h3>Requested sizes and colours</h3><div class="table-scroll"><table><thead><tr><th>Size</th><th>Colour</th><th>Pieces</th></tr></thead><tbody>{#each detail.record.variants as v}<tr><td>{v.size}</td><td>{v.colour}</td><td>{v.quantity}</td></tr>{/each}</tbody></table></div>
 <details><summary>Review sample BOM ({detail.record.bom.length} components)</summary><div class="table-scroll"><table><thead><tr><th>Group / component</th><th>Reference</th><th>Quantity / unit</th><th>Details</th></tr></thead><tbody>{#each detail.record.bom as b}<tr><td>{b.group} · {b.component}</td><td>{b.reference||'—'}</td><td>{b.quantity||'—'} {b.unit||''}</td><td>{[b.colour,b.size,b.ticket,b.thread_position,b.shade,b.placement,b.remarks].filter(Boolean).join(' · ')}</td></tr>{/each}</tbody></table></div></details>
 {#if detail.record.status==='Submitted'&&data.can_approve}<div class="review"><label>MD review note<textarea bind:value={review}></textarea></label><button class="button primary" disabled={busy} onclick={()=>decide('approve')}>Approve and generate indents</button><button class="button secondary" disabled={busy||!review.trim()} onclick={()=>decide('return')}>Return for changes</button></div>{/if}
 <h3>Documents and images</h3><p>Files remain private to users with access to this request.</p><ul>{#each detail.files as f}<li><a href={'/api/sample-files/'+f.id}>{f.indent_id?'Indent #'+f.indent_id+' · ':''}{f.category}: {f.name}</a></li>{:else}<li>No documents uploaded.</li>{/each}</ul>
 {#if detail.record.status!=='Submitted'&&((data.can_edit&&detail.record.status!=='Approved')||detail.record.status==='Approved'&&(data.can_produce||data.can_audit||data.can_pattern||data.can_handover))}<div class="variant"><label>Document category<select bind:value={category}>{#each ['Buyer email','Buyer specification','Sample to copy','CAD','Labels','Audit sheet','Fabric swatch','Trim card','Sample images','Dispatch','Buyer feedback','Other'] as c}<option>{c}</option>{/each}</select></label><label>Link to indent<select bind:value={fileIndent}><option value="">Whole request</option>{#each detail.pieces as p}<option value={String(p.id)}>#{p.id} · {p.size} · {p.colour}</option>{/each}</select></label><label>Upload files (10 MB each)<input type="file" multiple disabled={busy} onchange={upload} accept=".eml,.pdf,.docx,.xlsx,.csv,.txt,.png,.jpg,.jpeg,.dxf,.zip"/></label></div>{/if}
 <h3>Individual indents</h3>{#each detail.pieces as piece (piece.id)}<SamplePiece {piece} {data} onchange={refreshDetail} onprint={print} onissue={()=>stockForm={company_id:detail.record.company_id,material_id:detail.record.profile.alternate_material_id||detail.record.profile.material_id,indent_id:piece.id,metres:'',reference:''}}/>{:else}<p>Indent numbers are generated after MD approval.</p>{/each}
 <h3>Fabric issues</h3>{#each detail.issues as i}<p><strong>SDC-{String(i.id).padStart(7,'0')}</strong> · Indent #{i.indent_id} · {i.code} · {Math.abs(Number(i.metres))} m</p>{:else}<p>No fabric issues recorded.</p>{/each}
 <details><summary>History</summary>{#each detail.history as h}<p>{new Date(h.created_at).toLocaleString()} · {h.actor} · {h.action}</p>{/each}</details>
 </div></div>
{/if}
{#if stockForm}<div class="sample-overlay top"><div role="dialog" aria-modal="true" aria-label="Sample fabric stock" tabindex="-1" class="sample-dialog small" use:enter><h2>{stockForm.indent_id?'Issue fabric · #'+stockForm.indent_id:'Receive sample fabric'}</h2>{#if error}<p class="form-error" role="alert">{error}</p>{/if}<label>Fabric<select bind:value={stockForm.material_id}><option value="">Select…</option>{#each data.materials.filter((m:any)=>m.company_id===Number(stockForm.company_id)) as m}<option value={m.id}>{m.code}</option>{/each}</select></label><label>Metres<input type="number" min="0.001" step="0.001" bind:value={stockForm.metres}/></label>{#if !stockForm.indent_id}<label>Receipt / DC reference<input bind:value={stockForm.reference}/></label>{/if}<footer><button class="button primary" disabled={busy} onclick={stockSave}>Save stock movement</button><button class="button secondary" disabled={busy} onclick={()=>stockForm=null}>Cancel</button></footer></div></div>{/if}
{#if detail}<div class="sample-print" aria-hidden="true">{#if printMode==='indent'}{#each printPieces as piece}<section class="print-sheet"><header><img src="/logo.png" alt="Euro Suits"/><div><h1>EURO SUITS · SAMPLE REQUEST</h1><h2>Indent #{piece.id} · {piece.size} · {piece.colour}</h2><p>SR-{detail.record.id} · {companies.find(c=>c.id===detail.record.company_id)?.name} · {piece.status}</p><p>Buyer: {detail.record.buyer_name} · Merchant: {detail.record.merchant}</p></div></header><div class="print-fields">{#each fields as [key,title]}{#if detail.record.profile[key]}<div><strong>{title}</strong> {key.includes('material_id')?material(detail.record.profile[key]):detail.record.profile[key]}</div>{/if}{/each}</div><h3>Sample BOM</h3><table><thead><tr><th>Group / component</th><th>Reference</th><th>Qty / unit</th><th>Colour / size / thread / remarks</th></tr></thead><tbody>{#each detail.record.bom as b}<tr><td>{b.group} / {b.component}</td><td>{b.reference||''}</td><td>{b.quantity||''} {b.unit||''}</td><td>{[b.colour,b.size,b.ticket,b.thread_position,b.shade,b.placement,b.remarks].filter(Boolean).join(' · ')}</td></tr>{/each}</tbody></table><p>{#each detail.issues.filter((i:any)=>i.indent_id===piece.id) as issue}DC: SDC-{String(issue.id).padStart(7,'0')} · {issue.code} · {Math.abs(Number(issue.metres))} m {/each}</p><h3>Production, audit and handover</h3><div class="print-fields">{#each Object.entries(piece.production) as [k,v]}{#if v&&k!=='audit_reports'}<div><strong>{label(k)}</strong> {String(v)}</div>{/if}{/each}</div></section>{/each}{:else if printMode==='audit'||printMode==='dispatch'}{#each printPieces as piece}<SampleReports {piece} record={detail.record} kind={printMode} {material}/>{/each}{:else}{#each layoutPages as boxes,index}<section class="print-sheet"><h1>EURO SUITS · SAMPLE LAYOUT</h1><p>SR-{detail.record.id} · {detail.record.profile.buyer_style} · EST {detail.record.profile.est} · Page {index+1}</p><div class="swatch-grid">{#each Array.from({length:6}) as _,i}<div><strong>{boxes[i]?.group||''} · {boxes[i]?.component||'Swatch'}</strong><p>Reference: {boxes[i]?.reference||''}</p><p>Colour: {boxes[i]?.colour||''} · Qty: {boxes[i]?.quantity||''}</p><small>Attach swatch here</small></div>{/each}</div></section>{/each}{/if}</div>{/if}
<style>
 .sample-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.sop li{margin:14px 0;line-height:1.7}
